-- PT124-S2-Q18. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT124-S2-Q18$batch10$ AND q.stimulus=$batch10$Tallulah: The columnist attributes the decline of interest in novels to consumerism, technology, and the laziness of people who prefer watching television to reading a novel. However, in reaching this conclusion, the columnist has overlooked important evidence. It is surely relevant that contemporary fiction is frequently of poor quality—indeed, much of it is meaningless and depressing—whereas many good newspapers, magazines, professional journals, and books of other types are currently available.$batch10$ AND q.prompt=$batch10$Which one of the following most accurately expresses the main conclusion of Tallulah's argument?$batch10$ AND q.correct_choice=$batch10$C$batch10$) THEN RAISE EXCEPTION 'Question changed: PT124-S2-Q18'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT124-S2-Q18$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT124-S2-Q18'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT124-S2-Q18$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Opposing Point$batch10$, $batch10$The columnist blames the decline of interest in novels on consumerism, technology, and lazy television viewers.$batch10$), (1, $batch10$Conclusion$batch10$, $batch10$The columnist has overlooked important evidence.$batch10$), (2, $batch10$Evidence$batch10$, $batch10$Contemporary fiction is often poor quality, while many good newspapers, magazines, journals, and other books are available.$batch10$), (3, $batch10$Evaluate$batch10$, $batch10$Tallulah doesn't say the columnist's causes are wrong. Tallulah says the columnist missed something relevant. The last sentence is the evidence that was missed.$batch10$), (4, $batch10$Goal$batch10$, $batch10$The columnist reached that view without considering all the relevant evidence.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT124-S2-Q18$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$Tallulah offers the poor quality of fiction as overlooked evidence, not as the proven cause of novels' decline.$batch10$), ($batch10$B$batch10$, $batch10$Tallulah never says the columnist's explanation is false, only that it ignored relevant evidence.$batch10$), ($batch10$C$batch10$, $batch10$"Overlooked important evidence" is the same as forming a view "without considering all of the pertinent evidence."$batch10$), ($batch10$D$batch10$, $batch10$Tallulah never claims people read as much as before.$batch10$), ($batch10$E$batch10$, $batch10$This is part of the evidence the columnist overlooked.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT124-S2-Q18$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
